def num_islands(grid):
    """
    Counts the number of islands in the given grid.
    An island is surrounded by water ('0') and is formed by connecting adjacent lands ('1').
    :param grid: List of lists containing '1's and '0's
    :return: Integer representing the number of islands
    """
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] == '1':
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    island_count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '1' and not visited[i][j]:
                visited[i][j] = True
                dfs(i, j)
                island_count += 1
    return island_count
