def pairSum(arr, target):
    """
    Returns True if there are two distinct numbers in the array that add up to the target sum,
    otherwise returns False.
    """
    if len(arr) < 2:
        return False

    hash_map = {}

    for number in arr:
        complement = target - number
        if complement in hash_map:
            return True
        hash_map[number] = True

    return False
