def get_primes_desc(numbers: list) -> list:
    """
    Returns a list of prime numbers from the input list, arranged in descending order.
    Duplicate primes are kept in their original order of appearance.
    """
    prime_digits = set()
    for number in numbers:
        if number <= 1:
            continue
        if number < 2:
            continue
        for divisor in range(2, int(number**0.5) + 1):
            if number % divisor == 0:
                prime_digits.remove(number)
                prime_digits.remove(divisor)
    return sorted(prime_digits, reverse=True)
